/*
 * The texts and number tables ALIFE.EXE carries inside itself, and the
 * credits, compiled into the port. The .c files next to this header are
 * GENERATED by tools/extract_exe.py from the Windows 95 ALIFE.EXE and
 * committed; the build never runs the generator. Image data (the built-in
 * font's glyphs, the cursor and icon resources) is not here: gfx/exe_res.c
 * reads it from the user's ALIFE.EXE at runtime.
 *
 * Game code doesn't use these directly: gfx/exe_res.h (by address and by
 * resource id), ui/exe_text.h and ui/about.c sit on top.
 */
#ifndef AFTERLIFE_DATA_EXE_DATA_H
#define AFTERLIFE_DATA_EXE_DATA_H

#include <stddef.h>
#include <stdint.h>

/* ---- exe_image.c: .rdata and .data by virtual address ---- */

/* `len` bytes at `va`; `bytes` is a string literal (it may hold NULs). */
typedef struct {
    uint32_t va;
    uint32_t len;
    const char *bytes;
} ExePiece;

/* A section: the raw (file) size starting at `va`, zero where no piece is. */
typedef struct {
    uint32_t va;
    uint32_t size;
    const ExePiece *pieces;
    size_t n_pieces;
} ExeSection;

#define EXE_SECTIONS 2
extern const ExeSection exe_sections[EXE_SECTIONS];

/* Image data within the sections: zero in the pieces, copied from the
 * user's ALIFE.EXE when gfx/exe_res.c loads it. */
typedef struct {
    uint32_t va;
    uint32_t len;
} ExeRegion;

extern const ExeRegion exe_image_regions[];
extern const size_t exe_n_image_regions;

/* ---- credits_script.c: the about box's credits ---- */

typedef enum {
    CREDITS_ADD,    /* credits_add(kind, text, x, y, arg or font slot, flags) */
    CREDITS_RAND,   /* var = rand_range(lo, hi) */
    CREDITS_SWITCH, /* var < n_cases ? goto cases[var] : goto target (unsigned) */
    CREDITS_GOTO,   /* goto target */
    CREDITS_END,
} CreditsOpKind;

typedef struct {
    CreditsOpKind op;
    int kind;         /* ADD */
    const char *text; /* ADD of a text entry */
    int32_t x, y;     /* ADD */
    int font;         /* ADD: 0..2 = the font slot (small1, small2, big) as arg; -1 = `arg` */
    int32_t arg;      /* ADD */
    uint32_t flags;   /* ADD */
    int var;          /* RAND, SWITCH: the local variable (frame offset) */
    int32_t lo, hi;   /* RAND */
    int target;       /* SWITCH (default), GOTO: an op index */
    int n_cases;      /* SWITCH */
    int cases[8];     /* SWITCH: op indexes */
} CreditsOp;

extern const CreditsOp credits_script[];
extern const size_t credits_script_len;

#endif
